#ifdef SV57_SUPPORTED
# ---- sv57: hypervisor Svukte behavior ----
# S-stage Bare: the HS-mode and U-mode code below runs untranslated, so only the
# VS-stage mappings matter and no S-stage page tables are needed.
  csrw satp, zero
  sfence.vma
# G-stage Bare, so guest physical addresses are physical addresses.
  csrw hgatp, zero
# Keep ecall undelegated so RVTEST_GOTO_MMODE reaches M-mode from VU-mode.
  csrw hedeleg, zero
# VS-stage mappings. Superpages only, so rvtest_Vroot_pg_tbl holds every leaf PTE.
  SUPERPAGE_VS_PTE_SETUP(sv57, rvtest_code_begin, (PTE_D | PTE_A | PTE_U | PTE_X | PTE_R | PTE_V), 0x5000080000000, LEVEL4)
  SUPERPAGE_VS_PTE_SETUP(sv57, rvtest_data_1, (PTE_D | PTE_A | PTE_U | PTE_X | PTE_W | PTE_R | PTE_V), 0xff00000000000000, LEVEL4)
  SUPERPAGE_VS_PTE_SETUP(sv57, rvtest_data_1, (PTE_D | PTE_A | PTE_X | PTE_W | PTE_R | PTE_V), 0xff01000000000000, LEVEL4)
  SUPERPAGE_VS_PTE_SETUP(sv57, rvtest_data_1, (PTE_D | PTE_A | PTE_U | PTE_X | PTE_W | PTE_R | PTE_V), 0x1000000000000, LEVEL4)
  hfence.vvma
# Point the VS save area's code pointer at the code region's virtual address so
# RVTEST_GOTO_LOWER_MODE VUmode relocates its return address. a0 is not
# allocatable, but V_SAVE_AREA_SETUP requires it and no mode switch intervenes.
  csrr a0, mscratch
  V_SAVE_AREA_SETUP(0x5000080000000, rvtest_code_begin, code, LEVEL4)
  VSATP_SETUP(sv57, PA)
  hfence.vvma

